<div class="mb-8"><div class="text-sm text-gray-500">Editorial workflow</div><h1 class="display text-4xl font-bold">Edit article</h1></div><form method="post" action="/admin/articles/save" class="grid lg:grid-cols-[1.3fr_.7fr] gap-6"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($article['id'])?>"><section class="bg-white rounded-2xl shadow-sm p-6 space-y-4"><input name="title" required value="<?=e($article['title'])?>" placeholder="Headline" class="w-full display text-3xl font-bold border-b border-gray-200 pb-3"><input name="slug" required value="<?=e($article['slug'])?>" placeholder="Slug" class="w-full rounded-lg border border-gray-200 px-3 py-2"><textarea name="summary" rows="3" placeholder="Summary" class="w-full rounded-lg border border-gray-200 px-3 py-2"><?=e($article['summary'])?></textarea><textarea name="content" required rows="18" placeholder="Article body" class="w-full rounded-lg border border-gray-200 px-3 py-2"><?=e($article['content'])?></textarea></section><aside class="bg-white rounded-2xl shadow-sm p-6 space-y-4"><label class="text-sm font-medium">Category<select name="category_id" class="mt-2 w-full rounded-lg border border-gray-200 px-3 py-2"><option value="">Uncategorized</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=$article['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><input name="tags" placeholder="Tags, comma separated" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input name="seo_title" value="<?=e($article['seo_title'])?>" placeholder="SEO title" class="w-full rounded-lg border border-gray-200 px-3 py-2"><textarea name="meta_description" rows="3" placeholder="Meta description" class="w-full rounded-lg border border-gray-200 px-3 py-2"><?=e($article['meta_description'])?></textarea><input name="featured_image" value="<?=e($article['featured_image'])?>" placeholder="Featured image URL" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input name="source_name" value="<?=e($article['source_name'])?>" placeholder="Source name" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input name="source_url" value="<?=e($article['source_url'])?>" placeholder="Original source URL" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input type="hidden" name="ai_generated" value="<?=!empty($article['ai_generated'])?'1':'0'?>"><div class="flex gap-3"><button name="status" value="draft" class="flex-1 rounded-lg border border-gray-300 py-3 font-semibold">Save draft</button><button name="status" value="published" class="flex-1 rounded-lg bg-[#b8e64b] py-3 font-semibold">Publish</button></div></aside></form>
